91","year":2022,"line":"IDIS-REACT","beneficiary":"SILMOR 2011, S.L.","feder_beneficiary_id":"ES51EL53","operation_name":"SILMOR 2011, S.L.","description":"El proyecto de inversión de SILMOR 2011, S.L. consiste en la incorporación de medios productivos para la PLANTA DE TRATAMIENTO DE ARENAS DE SÍLICE y la construcción de un edificio para el fin de produceso productivo (SECADERO). Con ello se conseguirá incrementar la capacidad productiva de la planta en las líneas de negocio de la empresa de arenas de sílice y morteros. Con esta inversión podremos atender a la demanda del mercado actual y crecer aún más en las ventas de las dos líneas de negocio de la empresa.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":49387.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Calatayud","municipality_code":"50067","intervention":"071 Desarrollo y promoción de empresas especializadas en prestación de servicios que contribuyen a la economía con bajas emisiones de carbono y a la resistencia al cambio climático (incluyendo el apoyo a dichos servicios)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=1213","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":1213,"source_updated":"2025-05-29"}],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[],"fields":{"nif":"","project_description":"","municipality":"","province":"","project_start_dates":"","project_end_dates":""}},"province":null},{"import_key":"58fc254a7d2dc4f212d46001","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inver