sion":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[{"operation_code":"2020010","year":2020,"line":"TDI-FEDER (antecedente)","beneficiary":"BMC MAQUINARIA AGRICOLA S.L.","feder_beneficiary_id":"ES51NN61","operation_name":"BMC AGRICOLA, S.L.","description":"La primera fase del proyecto consiste en la realización de un soporte \"tripuntal\" que mediante dos células de carga permite el pesaje continuo de la cantidad de abono de la abonadora KOPA junto con el control de la apertura de las boquillas de descarga mediante dos motores eléctricos y la incorporación de un sistema de GPS que mide la velocidad lineal de la máquina, de manera que gracias al desarrollo de un software logramos tener una dosificación constante","start_date":"01/10/2019","end_date":"31/12/2020","feder_operation_cost":30248.9,"eu_cofinancing_percent":50.0,"province":"Zaragoza","municipality":"Magallón","municipality_code":"50153","intervention":"001 Inversión productiva genérica en pequeñas y medianas –empresas («PYME»)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=156","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":156,"source_updated":"2025-05-29"},{"operation_code":"2021018","year":2021,"line":"TDI-FEDER (antecedente)","beneficiary":"BMC MAQUINARIA AGRICOLA S.L.","feder_beneficiary_id":"ES51NN61","operation_name":"BMC AGRICOLA, S.L.","description":"\"Rediseño de elementos de abonadora modelo ADH, en base a simulación de MED, e integración de sensores de detección de presencia, y actuadores hidráulicos gestionados por un microcontrolador, permiten distribuir abono en una parcela de arbolado, lineal y únicamente en zonas cercanas al árbol, ahorrando entre un 40% y un 60% de abono\"","start_date":"01/01/2020","end_date":"31/12/2020","feder_operation_cost":92215.95,"eu_cofinancing_percent":50.0,"province":"Zaragoza","municipality":"Magallón","municipality_code":"50153","intervention":"001 Inversión productiva genérica en pequeñas y medianas –empresas («PYME»)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=241","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":241,"source_updated":"2025-05-29"},{"operation_code":"2021124","year":2021,"line":"TDI-FEDER (antecedente)","beneficiary":"BMC MAQUINARIA AGRICOLA S.L.","feder_beneficiary_id":"ES51NN61","operation_name":"BMC MAQUINARIA AGRICOLA, S.L.","description":"Rediseño de una abonadora KOPA mediante el estudio de sus funcionalidades y el análisis de soluciones de la competencia para desarrollar, hasta la definición final de producto, una nueva versión que incorpore nuevas características atendiendo a los requisitos de los nuevos usuarios.","start_date":"01/01/2020","end_date":"15/11/2021","feder_operation_cost":9145.0,"eu_cofinancing_percent":50.0,"province":"Zaragoza","municipality":"Magallón","municipality_code":"50153","intervention":"001 Inversión productiva genérica en pequeñas y medianas –empresas («PYME»)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=319","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":319,"source_updated":"2025-05-29"},{"operation_code":"D2022020","year":2022,"line":"IDIS-REACT","beneficiary":"BMC MAQUINARIA AGRICOLA S.L.","feder_beneficiary_id":"ES51NN61","operation_name":"BMC MAQUINARIA AGRICOLA, S.L.","description":"\"Este proyecto ha conseguido innovar en materia de organización en el antiguo y en el nuevo centro de trabajo de BMC aplicando nuevos procesos que transforman el método de producción y de suministro mejorándolos significativamente Para conseguirlo, se han transformado los procesos de stockage, ensamblaje, almacenaje y expedición dotándolos de tecnología suficiente e incorporando un sistema de gestión avanzado conectado al ERP de la empresa de manera que la comunicación entre la oficina técnica, la gerencia, el departamento comercial, el almacén y la línea de montaje, sea mas fluida preparando los centros de trabajo para ser una Smart Factory en un futuro próximo\"","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":12256.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Magallón","municipality_code":"50153","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=559","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":559,"source_updated":"2025-05-29"},{"operation_code":"AR_OP000051","project_code":"TDI2023022_E_P050","year":2023,"line":"TDI-FEDER","beneficiary":"BMC MAQUINARIA AGRICOLA S.L.","feder_beneficiary_id":"ES51N0000N61","nif":"B50633015","operation_name":"BMC MAQUINARIA AGRICOLA S.L.","description":"El proyecto consiste en disen~ar un equipo de aplicacio´n de fertilizantes donde el mecanismo de transporte del producto sea neuma´tico. El objetivo de este desarrollo es obtener un equipo el cual combine las ventajas de un equipo de aplicacio´n de fitosanitarios y de un sistema de distribucio´n","start_date":"01/09/2022","end_date":"31/03/2025","award_document_date":"01/12/2023","feder_operation_cost":13792.0,"eu_cofinancing_percent":40.0,"province":"Zaragoza","municipality":"","intervention":"027 - Procesos de innovación en las pymes (procesos, organización, comercialización, creación conjunta, e innovación centrada en los usuarios e impulsada por la demanda) - 100.00%","source_url":"https://app.powerbi.com/view?r=eyJrIjoiNjk4NmRmZjctMzg5Yi00OTQxLTg2ZjgtNTc2NWUyN2I2ZTRjIiwidCI6IjEwNmQ2ZDMyLTU2ODktNGMwZi1hNTdkLTI2MzFmMWZkMWYyOCIsImMiOjl9","source_file":"feder-aragon-2021-2027-20261